/**
 * Shared column helpers used across every table.
 *
 * Money convention (Section 14): every monetary value is stored as an integer
 * number of MINOR UNITS (cents) in a `bigint`, always paired with an explicit
 * 3-letter `currency` column on the same table. No floats, no single-currency
 * assumption — Stripe does automatic currency conversion.
 */
import { bigint, char, timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key, generated by Postgres (`gen_random_uuid()`, core in PG13+). */
export const pk = () => uuid("id").primaryKey().defaultRandom();

/** ISO-4217 currency code, e.g. "USD". */
export const currency = (name = "currency") => char(name, { length: 3 });

/** Money in minor units (cents). Pair with a `currency` column. Nullable by
 *  default; add `.notNull().default(0)` at the call site where appropriate. */
export const money = (name: string) => bigint(name, { mode: "number" });

/** created_at / updated_at, timezone-aware, auto-managed. */
export const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};
